// Canvas Confetti Lightweight Engine
(function() {
  var confetti = (function() {
    var defaultCanvas = null;

    function getCanvas() {
      if (defaultCanvas) return defaultCanvas;
      defaultCanvas = document.createElement('canvas');
      defaultCanvas.id = 'confetti-canvas';
      defaultCanvas.style.position = 'fixed';
      defaultCanvas.style.top = '0';
      defaultCanvas.style.left = '0';
      defaultCanvas.style.width = '100vw';
      defaultCanvas.style.height = '100vh';
      defaultCanvas.style.zIndex = '999999';
      defaultCanvas.style.pointerEvents = 'none';
      document.body.appendChild(defaultCanvas);
      resizeCanvas();
      window.addEventListener('resize', resizeCanvas);
      return defaultCanvas;
    }

    function resizeCanvas() {
      if (!defaultCanvas) return;
      defaultCanvas.width = window.innerWidth * window.devicePixelRatio;
      defaultCanvas.height = window.innerHeight * window.devicePixelRatio;
    }

    var particles = [];
    var animationId = null;

    function randomRange(min, max) {
      return Math.random() * (max - min) + min;
    }

    var colors = ['#ff4d6d', '#ff758f', '#ff8fa3', '#c9184a', '#a53860', '#ffd166', '#06d6a0', '#118ab2', '#a0c4ff', '#bdb2ff', '#ffc6ff'];

    function createParticle(x, y, options) {
      var angle = options.angle !== undefined ? options.angle * (Math.PI / 180) : randomRange(0, Math.PI * 2);
      var spread = options.spread !== undefined ? options.spread * (Math.PI / 180) : Math.PI / 2;
      var actualAngle = angle + (Math.random() - 0.5) * spread;
      var velocity = randomRange(options.velocityMin || 25, options.velocityMax || 55);

      return {
        x: x * window.devicePixelRatio,
        y: y * window.devicePixelRatio,
        vx: Math.cos(actualAngle) * velocity,
        vy: Math.sin(actualAngle) * velocity - randomRange(5, 15),
        size: randomRange(6, 12) * window.devicePixelRatio,
        color: (options.colors || colors)[Math.floor(Math.random() * (options.colors || colors).length)],
        rotation: randomRange(0, 360),
        rotationSpeed: randomRange(-10, 10),
        gravity: options.gravity || 0.6,
        drag: 0.96,
        opacity: 1,
        decay: randomRange(0.008, 0.015),
        shape: Math.random() > 0.4 ? 'rect' : (Math.random() > 0.5 ? 'heart' : 'circle')
      };
    }

    function drawHeart(ctx, x, y, size) {
      var s = size / 2;
      ctx.beginPath();
      ctx.moveTo(x, y + s / 4);
      ctx.quadraticCurveTo(x, y, x + s / 2, y);
      ctx.quadraticCurveTo(x + s, y, x + s, y + s / 2);
      ctx.quadraticCurveTo(x + s, y + s, x, y + s * 1.5);
      ctx.quadraticCurveTo(x - s, y + s, x - s, y + s / 2);
      ctx.quadraticCurveTo(x - s, y, x - s / 2, y);
      ctx.quadraticCurveTo(x, y, x, y + s / 4);
      ctx.fill();
    }

    function loop() {
      if (particles.length === 0) {
        cancelAnimationFrame(animationId);
        animationId = null;
        var canvas = getCanvas();
        var ctx = canvas.getContext('2d');
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        return;
      }

      var canvas = getCanvas();
      var ctx = canvas.getContext('2d');
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (var i = particles.length - 1; i >= 0; i--) {
        var p = particles[i];
        p.vx *= p.drag;
        p.vy *= p.drag;
        p.vy += p.gravity;
        p.x += p.vx;
        p.y += p.vy;
        p.rotation += p.rotationSpeed;
        p.opacity -= p.decay;

        if (p.opacity <= 0 || p.y > canvas.height + 50) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rotation * Math.PI) / 180);
        ctx.globalAlpha = Math.max(0, p.opacity);
        ctx.fillStyle = p.color;

        if (p.shape === 'heart') {
          drawHeart(ctx, 0, 0, p.size);
        } else if (p.shape === 'circle') {
          ctx.beginPath();
          ctx.arc(0, 0, p.size / 2, 0, Math.PI * 2);
          ctx.fill();
        } else {
          ctx.fillRect(-p.size / 2, -p.size / 2, p.size, p.size * 0.6);
        }
        ctx.restore();
      }

      animationId = requestAnimationFrame(loop);
    }

    function fire(options) {
      options = options || {};
      var count = options.particleCount || 60;
      var x = options.origin && options.origin.x !== undefined ? options.origin.x * window.innerWidth : window.innerWidth / 2;
      var y = options.origin && options.origin.y !== undefined ? options.origin.y * window.innerHeight : window.innerHeight / 2;

      for (var i = 0; i < count; i++) {
        particles.push(createParticle(x, y, options));
      }

      if (!animationId) {
        animationId = requestAnimationFrame(loop);
      }
    }

    function celebratoryBurst() {
      // Multiple staggered bursts
      fire({ particleCount: 80, spread: 80, origin: { x: 0.5, y: 0.6 } });
      setTimeout(function() {
        fire({ particleCount: 50, angle: 60, spread: 60, origin: { x: 0.1, y: 0.7 } });
        fire({ particleCount: 50, angle: 120, spread: 60, origin: { x: 0.9, y: 0.7 } });
      }, 250);
      setTimeout(function() {
        fire({ particleCount: 90, spread: 120, origin: { x: 0.5, y: 0.4 } });
      }, 600);
    }

    return {
      fire: fire,
      burst: celebratoryBurst
    };
  })();

  window.confetti = confetti;
})();
